/* From Uiverse.io by Shoh2008 - Tags: loader */
.__UIV_SCOPE__ .loader {
  position: relative;
  border: 24px solid;
  border-color: red  transparent red transparent;
  animation: rotate_000 2s linear infinite;
}

.__UIV_SCOPE__ .loader:before,
      .__UIV_SCOPE__ .loader:after {
  content: "";
  display: block;
  border: 24px solid transparent;
  border-left-color: red;
  position: absolute;
  left: -24px;
  top: -24px;
  animation: prix 1s infinite ease-in;
  transform-origin: 0% 100%;
}

.__UIV_SCOPE__ .loader:before {
  border-color: transparent red transparent transparent;
  transform-origin: 100% 0%;
  animation-delay: 0.5s;
}

@keyframes rotate_000 {
  100% {
    transform: rotate(360deg)
  }
}

@keyframes prix {
  20% , 80% {
    transform: rotate(0)
  }

  50% {
    transform: rotate(-90deg)
  }
}
